/**
 * Maps are generated by small builder programs into ASCII grids (see LEGEND), then rendered by WorldScene.
 * To add a map: write a builder function and register it in MAPS with NPCs, warps, chests, etc.
 */
import type { Look } from '../systems/state';

export const LEGEND: Record<string, { t: number; solid?: boolean; over?: number; enc?: boolean; anim?: number }> = {
  '.': { t: 0 }, ',': { t: 1 }, '"': { t: 2, enc: true }, '*': { t: 3 }, ':': { t: 4 }, '~': { t: 6, solid: true, anim: 7 },
  'T': { t: 9, solid: true, over: 10 }, 'P': { t: 51, solid: true, over: 52 }, '#': { t: 11, solid: true }, 'w': { t: 12, solid: true }, 'D': { t: 13 },
  'r': { t: 14, solid: true }, 'R': { t: 15, solid: true }, 'u': { t: 16, solid: true }, 'U': { t: 17, solid: true }, 'F': { t: 18, solid: true },
  '=': { t: 19 }, 'o': { t: 20 }, 'L': { t: 46, solid: true }, 'b': { t: 31, solid: true }, 'h': { t: 44, solid: true }, 'W': { t: 34, solid: true },
  'S': { t: 47, solid: true }, 'c': { t: 35, solid: true }, 'C': { t: 36, solid: true }, 'x': { t: 50, solid: true },
  '_': { t: 27 }, '|': { t: 28, solid: true }, 'k': { t: 29, solid: true }, 'g': { t: 30 }, 'B': { t: 37, solid: true }, 'K': { t: 38, solid: true },
  'O': { t: 39, solid: true }, 'X': { t: 40, solid: true }, 't': { t: 48, solid: true }, 'H': { t: 49, solid: true },
  'd': { t: 21 }, 'e': { t: 22 }, 'M': { t: 24, solid: true }, 'm': { t: 23, solid: true }, 'a': { t: 25, solid: true }, 'l': { t: 26, solid: true },
  'v': { t: 32 }, '^': { t: 33 }, 'q': { t: 45 }, 's': { t: 43 }, 'y': { t: 42, solid: true }, ' ': { t: 41, solid: true },
};

export interface NpcDef { id: string; name: string; x: number; y: number; dir?: number; look?: Look; equip?: Record<string, string>; sprite?: string; script: string; wander?: boolean; hidden?: boolean; cond?: string; notCond?: string; counter?: boolean }
export interface WarpDef { x: number; y: number; to: string; tx: number; ty: number; dir?: number; cond?: string; blockScript?: string }
export interface ChestDef { id: string; x: number; y: number; item?: string; gold?: number }
export interface TriggerDef { x: number; y: number; w?: number; h?: number; script: string; once?: string; cond?: string }
export interface MapDef {
  id: string; name: string; music: string; grid: string[]; outdoor: boolean; dark?: number; ambient?: 'fireflies' | 'embers' | 'stars' | 'dust' | 'petals';
  npcs: NpcDef[]; warps: WarpDef[]; chests: ChestDef[]; triggers: TriggerDef[]; saves: { x: number; y: number }[];
  encounters?: { table: string; count: number; area?: [number, number, number, number] }; bg?: string; lights?: { x: number; y: number; c: number; r: number }[];
  signs?: { x: number; y: number; text: string }[]; torches?: boolean;
}

class B {
  g: string[][];
  constructor(public w: number, public h: number, fill: string) { this.g = Array.from({ length: h }, () => Array(w).fill(fill)); }
  set(x: number, y: number, c: string) { if (x >= 0 && y >= 0 && x < this.w && y < this.h) this.g[y][x] = c; return this; }
  get(x: number, y: number) { return this.g[y]?.[x]; }
  rect(x: number, y: number, w: number, h: number, c: string) { for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) this.set(x + i, y + j, c); return this; }
  frame(x: number, y: number, w: number, h: number, c: string) { for (let i = 0; i < w; i++) { this.set(x + i, y, c); this.set(x + i, y + h - 1, c); } for (let j = 0; j < h; j++) { this.set(x, y + j, c); this.set(x + w - 1, y + j, c); } return this; }
  hline(x0: number, x1: number, y: number, c: string) { for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++) this.set(x, y, c); return this; }
  vline(x: number, y0: number, y1: number, c: string) { for (let y = Math.min(y0, y1); y <= Math.max(y0, y1); y++) this.set(x, y, c); return this; }
  /** house: roof rows, eave row, wall row with door & windows */
  house(x: number, y: number, w: number, roof: 'r' | 'u', door: number, roofRows = 2) {
    const eave = roof === 'r' ? 'R' : 'U';
    this.rect(x, y, w, roofRows, roof); this.hline(x, x + w - 1, y + roofRows, eave);
    for (let i = 0; i < w; i++) this.set(x + i, y + roofRows + 1, i % 2 ? 'w' : '#');
    this.set(x + door, y + roofRows + 1, 'D'); return this;
  }
  scatter(c: string, n: number, x: number, y: number, w: number, h: number, on = '.', seed = 1) {
    let s = seed; const r = () => ((s = (s * 16807) % 2147483647) / 2147483647);
    for (let i = 0; i < n; i++) { const xx = x + Math.floor(r() * w), yy = y + Math.floor(r() * h); if (this.get(xx, yy) === on) this.set(xx, yy, c); } return this;
  }
  blob(cx: number, cy: number, rx: number, ry: number, c: string, seed = 3) {
    let s = seed; const r = () => ((s = (s * 16807) % 2147483647) / 2147483647);
    for (let y = cy - ry; y <= cy + ry; y++) for (let x = cx - rx; x <= cx + rx; x++) { const d = ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2; if (d < 0.75 + r() * 0.4) this.set(x, y, c); } return this;
  }
  /** dungeon: convert wall tops directly above floor into wall faces for a 3/4 look */
  faces() { for (let y = 0; y < this.h - 1; y++) for (let x = 0; x < this.w; x++) if (this.g[y][x] === 'm' && !LEGEND[this.g[y + 1][x]]?.solid) this.g[y][x] = 'M'; return this; }
  done() { return this.g.map(r => r.join('')); }
}

// ---------------------------------------------------------------- SPIRE (prologue)
function spire() {
  const b = new B(15, 18, ' ');
  b.blob(7, 9, 6, 7, 's', 5); b.rect(5, 2, 5, 3, 's'); b.rect(6, 15, 3, 3, 's');
  for (const [x, y] of [[3, 5], [11, 5], [3, 13], [11, 13]]) b.set(x, y, 'x');
  return b.done();
}
// ---------------------------------------------------------------- HOLLOWMERE village
function village() {
  const b = new B(32, 30, '.');
  b.scatter(',', 120, 0, 0, 32, 30, '.', 11);
  b.frame(0, 0, 32, 30, 'T'); b.frame(1, 1, 30, 28, 'T'); b.scatter('.', 30, 1, 1, 30, 28, 'T', 5);
  b.rect(2, 2, 28, 26, '.'); b.scatter(',', 80, 2, 2, 28, 26, '.', 17);
  // river and bridge
  b.vline(27, 0, 29, '~'); b.vline(28, 0, 29, '~'); b.set(27, 15, '='); b.set(28, 15, '='); b.vline(29, 2, 27, '.'); b.vline(30, 2, 27, 'T');
  // buildings
  b.house(2, 2, 9, 'r', 4); // Wayfarer's Hearth (door x=6,y=5)
  b.house(18, 2, 7, 'u', 3); // Shop (door x=21,y=5)
  b.house(3, 17, 6, 'r', 2); // Elder house (door x=5,y=20)
  // paths
  b.vline(6, 6, 8, ':'); b.vline(21, 6, 8, ':'); b.hline(6, 21, 8, ':'); b.vline(14, 8, 10, ':'); b.vline(15, 8, 10, ':');
  // plaza
  b.rect(11, 10, 9, 6, 'o'); b.set(11, 10, 'L'); b.set(19, 10, 'L'); b.set(11, 15, 'L'); b.set(19, 15, 'L');
  b.set(15, 12, 'x'); b.set(18, 14, 'W');
  b.vline(14, 16, 29, ':'); b.vline(15, 16, 29, ':'); b.hline(5, 14, 22, ':'); b.vline(5, 21, 22, ':');
  b.hline(20, 26, 14, ':'); b.hline(20, 26, 15, ':');
  // garden
  b.frame(19, 18, 7, 6, 'F'); b.set(22, 18, '.'); b.rect(20, 19, 5, 4, '*'); b.set(22, 19, ':'); b.set(22, 20, ':');
  b.scatter('*', 18, 2, 6, 24, 20, '.', 23); b.scatter('*', 14, 2, 6, 24, 20, ',', 29);
  b.set(8, 11, 'b'); b.set(9, 11, 'b'); b.set(23, 11, 'b'); b.set(3, 13, 'T'); b.set(24, 15, 'T'); b.set(10, 25, 'T'); b.set(20, 26, 'T'); b.set(3, 25, 'T');
  b.set(13, 18, 'S');
  // east bank
  b.set(29, 6, '.'); b.set(29, 24, '.');
  // south exit gap
  b.set(14, 28, ':'); b.set(15, 28, ':'); b.set(14, 29, ':'); b.set(15, 29, ':');
  b.set(9, 7, 'b'); b.set(17, 6, 'b'); b.set(25, 7, 'b');
  return b.done();
}
function hearth() {
  const b = new B(14, 11, '_');
  b.rect(0, 0, 14, 2, '|'); b.vline(0, 0, 10, '|'); b.vline(13, 0, 10, '|'); b.hline(0, 13, 10, '|');
  b.set(6, 1, 'H'); b.set(1, 1, 'K'); b.set(12, 1, 'K');
  b.hline(1, 4, 4, 'k'); b.vline(4, 2, 4, 'k'); // innkeeper counter
  b.hline(9, 12, 4, 'k'); b.vline(9, 2, 4, 'k'); // party ledger counter
  b.set(1, 7, 'B'); b.set(1, 8, 'B'); b.set(3, 7, 'B'); b.set(3, 8, 'B');
  b.set(8, 7, 't'); b.set(11, 7, 't'); b.set(12, 9, 'O');
  b.rect(6, 8, 2, 2, 'g'); b.set(6, 10, 'D'); b.set(7, 10, 'D');
  return b.done();
}
function shop() {
  const b = new B(13, 10, '_');
  b.rect(0, 0, 13, 2, '|'); b.vline(0, 0, 9, '|'); b.vline(12, 0, 9, '|'); b.hline(0, 12, 9, '|');
  b.hline(1, 3, 3, 'k'); b.hline(5, 7, 3, 'k'); b.hline(9, 11, 3, 'k');
  b.set(1, 1, 'K'); b.set(4, 1, 'X'); b.set(8, 1, 'O'); b.set(11, 1, 'K'); b.set(1, 6, 'O'); b.set(11, 6, 'X');
  b.rect(5, 6, 3, 2, 'g'); b.set(6, 9, 'D');
  return b.done();
}
function elder() {
  const b = new B(10, 9, '_');
  b.rect(0, 0, 10, 2, '|'); b.vline(0, 0, 8, '|'); b.vline(9, 0, 8, '|'); b.hline(0, 9, 8, '|');
  b.set(1, 1, 'K'); b.set(2, 1, 'K'); b.set(7, 1, 'H'); b.set(8, 2, 'B'); b.set(8, 3, 'B'); b.set(4, 4, 't'); b.set(1, 6, 'O');
  b.rect(4, 6, 2, 2, 'g'); b.set(4, 8, 'D');
  return b.done();
}
// ---------------------------------------------------------------- WHISPERWIND VALE (field)
function fields() {
  const b = new B(36, 44, '.');
  b.scatter(',', 260, 0, 0, 36, 44, '.', 41);
  b.frame(0, 0, 36, 44, 'T'); b.frame(1, 0, 34, 44, 'T'); b.scatter('P', 40, 2, 1, 32, 42, ',', 9);
  // entrance from village (top)
  b.rect(16, 0, 3, 3, ':');
  // winding path
  const path: [number, number][] = [[17, 0], [17, 6], [12, 6], [12, 14], [20, 14], [24, 14], [24, 22], [14, 22], [10, 22], [10, 30], [18, 30], [22, 30], [22, 36], [18, 36], [18, 40]];
  for (let i = 0; i + 1 < path.length; i++) { const [x0, y0] = path[i], [x1, y1] = path[i + 1]; if (x0 === x1) { b.vline(x0, y0, y1, ':'); b.vline(x0 + 1, y0, y1, ':'); } else { b.hline(x0, x1, y0, ':'); b.hline(x0, x1 + 1, y0 + 1, ':'); } }
  // tall grass fields (encounter zones visually)
  b.blob(26, 8, 6, 4, '"', 3); b.blob(6, 17, 4, 5, '"', 4); b.blob(29, 26, 4, 5, '"', 5); b.blob(16, 26, 4, 2, '"', 6); b.blob(6, 34, 4, 4, '"', 7); b.blob(28, 37, 5, 3, '"', 8);
  // pond
  b.blob(5, 9, 3, 3, '~', 12); b.set(5, 12, '.'); b.blob(30, 18, 3, 2, '~', 13);
  // forest clumps
  b.blob(18, 10, 3, 2, 'T', 14); b.blob(5, 26, 3, 2, 'T', 15); b.blob(16, 18, 3, 2, 'T', 16); b.blob(28, 31, 2, 2, 'T', 17); b.blob(14, 34, 2, 2, 'T', 18);
  b.scatter('*', 40, 2, 2, 32, 40, '.', 19); b.scatter('b', 16, 2, 2, 32, 40, ',', 21);
  // camp clearing with save crystal
  b.rect(19, 23, 6, 5, '.'); b.rect(20, 24, 4, 3, ','); b.set(21, 26, 'O');
  // ranch fence
  b.frame(25, 2, 8, 4, 'F'); b.set(28, 5, '.');
  // cave cliffs at bottom
  b.rect(2, 40, 32, 4, 'c'); b.hline(2, 33, 39, 'C'); b.set(18, 40, 'v'); b.set(19, 40, 'v'); b.set(18, 39, ':'); b.set(19, 39, ':');
  b.set(13, 3, 'S');
  return b.done();
}
// ---------------------------------------------------------------- CINDERDEEP HOLLOW (dungeon)
function hollow() {
  const b = new B(30, 34, 'm');
  // rooms
  b.rect(11, 26, 8, 6, 'd'); // entry
  b.rect(14, 18, 2, 8, 'd'); // corridor up
  b.rect(4, 14, 22, 5, 'd'); // great hall
  b.rect(3, 4, 6, 10, 'd'); // west wing
  b.rect(21, 4, 6, 10, 'd'); // east wing
  b.rect(9, 6, 12, 2, 'd'); // north corridor
  b.rect(12, 2, 6, 4, 'd'); // stairs chamber
  b.rect(23, 20, 4, 8, 'd'); b.rect(19, 25, 4, 2, 'd'); // side loop
  b.scatter('e', 80, 0, 0, 30, 34, 'd', 3); b.scatter('q', 6, 0, 0, 30, 34, 'd', 7);
  b.set(7, 16, 'l'); b.set(8, 16, 'l'); b.set(21, 16, 'l'); b.set(22, 17, 'l'); b.set(5, 8, 'a'); b.set(24, 10, 'a'); b.set(17, 28, 'a'); b.set(12, 28, 'a');
  b.set(15, 32, '^'); b.set(14, 32, '^'); b.set(14, 31, 'd'); b.set(15, 31, 'd');
  b.set(14, 2, 'v'); b.set(15, 2, 'v');
  b.faces();
  return b.done();
}
function lair() {
  const b = new B(17, 20, 'm');
  b.blob(8, 9, 7, 7, 'd', 4); b.rect(7, 15, 3, 5, 'd'); b.scatter('e', 30, 0, 0, 17, 20, 'd', 9);
  b.set(4, 6, 'l'); b.set(12, 6, 'l'); b.set(3, 11, 'l'); b.set(13, 12, 'l'); b.set(8, 3, 'q');
  b.set(8, 19, '^'); b.faces();
  return b.done();
}

